def maxAverageOfPath(cost, N): 
	dp = [[0 for _ in range(N + 1)] for _ in range(N + 1)]
	dp[0][0] = cost[0][0]
	for i in range(1, N): 
		dp[i][0] = cost[i][0] + dp[i - 1][0]
	for j in range(1, N): 
		dp[0][j] = dp[0][j - 1] + cost[0][j]
	for i in range(1, N): 
		for j in range(1, N): 
