def binomial_coeff(n, k): 
	C = [[0 for _ in range(k + 1)] for _ in range(1 + n)]
	for i in range(0, 1 + n): 
		for j in range(0, 1 + min(i, k)): 
			C[i][j] = 1 if j in [0, i] else (C[i - 1][j] + C[i - 1][j - 1])
	return C[n][k] 


def lobb_num(n, m): 
